define(["core/ajax"],function(Ajax){const init=function(flexbookId){document.querySelectorAll(".flexbook-content-flashcards").forEach(function(block){const visited=new Set;block.querySelectorAll(".flexbook-flashcard").forEach(function(card){card.addEventListener("click",function(){const flipped=card.getAttribute("aria-pressed")!=="true";card.setAttribute("aria-pressed",flipped?"true":"false");card.classList.toggle("is-flipped",flipped);if(flipped){visited.add(Number(card.dataset.itemIndex));Ajax.call([{methodname:"mod_flexbook_mark_content_completed",args:{flexbookid:flexbookId,contentid:Number(block.dataset.contentId),metric:visited.size,details:JSON.stringify({visited:Array.from(visited)})}}])[0].catch(function(){})}})})})};return{init:init}});